28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "possible_duplicate")
74	    private Boolean possibleDuplicate;
75	
76	    @Column(name = "possible_duplicate_of")
77	    private Integer possibleDuplicateOf;
78	
79	    @Transient
80	    private Integer householdMemberCount;
81	
82	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
83	    private Set<Pet> pets;
84	
85	    public String getAddress() {
86	        return this.address;
87	    }
88	
89	    public void setAddress(String address) {
90	        this.address = address;
91	    }
92	
93	    public String getCity() {
94	        return this.city;
95	    }
96	
97	    public void setCity(String city) {
98	        this.city = city;
99	    }
100	
101	    public String getTelephone() {
102	        return this.telephone;
103	    }
104	
105	    public void setTelephone(String telephone) {
106	        this.telephone = telephone;
107	    }
108	
109	    /**
110	     * Returns the stored E.164 {@code telephone} formatted for humans: the recognized country code
111	     * (with its leading {@code '+'}), a space, then the national digits grouped in threes from the
112	     * left and separated by spaces (for example {@code '+61412345678'} renders as
113	     * {@code '+61 412 345 678'}). The split into country code and national number reuses
114	     * {@link #countryCodeOf(String)}, the single definition of that split. Returns {@code null} when
115	     * the owner has no telephone, and returns the raw E.164 value unchanged when it carries no
116	     * recognized country code. This is the single definition of an owner's human-readable telephone.
117	     *
118	     * @return the human-formatted telephone, or {@code null} when the owner has no telephone
119	     */
120	    @Transient
121	    public String getTelephoneDisplay() {
122	        if (this.telephone == null) {
123	            return null;
124	        }
125	        String countryCode = countryCodeOf(this.telephone);
126	        if (countryCode == null) {
127	            return this.telephone;
128	        }
129	        String national = this.telephone.substring(1 + countryCode.length());
130	        StringBuilder display = new StringBuilder("+").append(countryCode);
131	        for (int i = 0; i < national.length(); i += 3) {
132	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
133	        }
134	        return display.toString();
135	    }
136	
137	    public String getEmail() {
138	        return this.email;
139	    }
140	
141	    public void setEmail(String email) {
142	        this.email = email;
143	    }
144	
145	    public String getPostcode() {
146	        return this.postcode;
147	    }
148	
149	    public void setPostcode(String postcode) {
150	        this.postcode = postcode;
151	    }
152	
153	    public LocalDate getRegistrationDate() {
154	        return this.registrationDate;
155	    }
156	
157	    public void setRegistrationDate(LocalDate registrationDate) {
158	        this.registrationDate = registrationDate;
159	    }
160	
161	    public LocalDate getBirthDate() {
162	        return this.birthDate;
163	    }
164	
165	    public void setBirthDate(LocalDate birthDate) {
166	        this.birthDate = birthDate;
167	    }
168	
169	    public String getCustomerCode() {
170	        return this.customerCode;
171	    }
172	
173	    public void setCustomerCode(String customerCode) {
174	        this.customerCode = customerCode;
175	    }
176	
177	    public String getHouseholdId() {
178	        return this.householdId;
179	    }
180	
181	    public void setHouseholdId(String householdId) {
182	        this.householdId = householdId;
183	    }
184	
185	    public Integer getNamesakeCount() {
186	        return this.namesakeCount;
187	    }
188	
189	    public void setNamesakeCount(Integer namesakeCount) {
190	        this.namesakeCount = namesakeCount;
191	    }
192	
193	    public Boolean getPossibleDuplicate() {
194	        return this.possibleDuplicate;
195	    }
196	
197	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
198	        this.possibleDuplicate = possibleDuplicate;
199	    }
200	
201	    public Integer getPossibleDuplicateOf() {
202	        return this.possibleDuplicateOf;
203	    }
204	
205	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
206	        this.possibleDuplicateOf = possibleDuplicateOf;
207	    }
208	
209	    public Integer getHouseholdMemberCount() {
210	        return this.householdMemberCount;
211	    }
212	
213	    public void setHouseholdMemberCount(Integer householdMemberCount) {
214	        this.householdMemberCount = householdMemberCount;
215	    }
216	
217	    /**
218	     * Builds the derived identity key that consolidates all owner duplicate detection into a
219	     * single value: the normalized E.164 {@code telephone}, the lower-cased {@code email}
220	     * (empty when none) and the {@code householdId} (empty when the owner shares no household),
221	     * joined by {@code '|'}. Two owners are duplicates exactly when their whole identity keys are
222	     * equal, so a difference in any of the three parts (for example two household mates with
223	     * different telephones) yields distinct keys. A {@code null} part contributes the empty string.
224	     *
225	     * @param telephone the normalized E.164 telephone
226	     * @param email the lower-cased email, or {@code null} when none
227	     * @param householdId the shared household identifier, or {@code null} when none
228	     * @return the derived identity key
229	     */
230	    public static String identityKey(String telephone, String email, String householdId) {
231	        return (telephone == null ? "" : telephone) + "|"
232	            + (email == null ? "" : email) + "|"
233	            + (householdId == null ? "" : householdId);
234	    }
235	
236	    /**
237	     * Returns this owner's derived identity key, see
238	     * {@link #identityKey(String, String, String)}.
239	     *
240	     * @return the derived identity key for this owner
241	     */
242	    @Transient
243	    public String getIdentityKey() {
244	        return identityKey(this.telephone, this.email, this.householdId);
245	    }
246	
247	    /**
248	     * Fixed telephone country-code table: the exact national-number length (the count of digits
249	     * following the country code) each country code this application recognizes admits
250	     * ({@code '61'} Australia => 9, {@code '1'} NANP => 10). Keyed by the country-code digits
251	     * without the leading {@code '+'}. A country code absent from this table is not recognized.
252	     */
253	    private static final Map<String, Integer> COUNTRY_CODE_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
254	
255	    /**
256	     * Resolves the recognized country code a normalized E.164 telephone carries: the longest entry
257	     * of the fixed country-code table (see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}) whose digits the
258	     * number begins with, so a shorter code can never shadow a longer one. Returns the country-code
259	     * digits without the leading {@code '+'} (for example {@code '61'} for {@code '+61412345678'}),
260	     * or {@code null} when the value is {@code null}, carries no leading {@code '+'}, or begins with
261	     * no recognized country code. This is the single definition of how an E.164 telephone splits
262	     * from its country code, shared by every rule that reasons about a telephone's country code.
263	     *
264	     * @param telephone the normalized E.164 telephone (a {@code '+'} followed by digits), or {@code null}
265	     * @return the recognized country-code digits, or {@code null} when none is recognized
266	     */
267	    public static String countryCodeOf(String telephone) {
268	        if (telephone == null || !telephone.startsWith("+")) {
269	            return null;
270	        }
271	        String digits = telephone.substring(1);
272	        return COUNTRY_CODE_NATIONAL_LENGTHS.keySet().stream()
273	            .filter(digits::startsWith)
274	            .max(Comparator.comparingInt(String::length))
275	            .orElse(null);
276	    }
277	
278	    /**
279	     * Resolves the exact national-number length (the count of digits following the country code) a
280	     * recognized country code admits using the fixed country-code table ({@code '61'} => 9,
281	     * {@code '1'} => 10, see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}). Returns the length, or
282	     * {@code null} when the country code is {@code null} or not recognized (it then carries no
283	     * per-country length rule). This is the single definition of the per-country national-number
284	     * lengths, shared by every rule that relates a telephone's national number to its country code.
285	     *
286	     * @param countryCode the country-code digits without the leading {@code '+'}, or {@code null}
287	     * @return the required national-number length, or {@code null} when the code is not recognized
288	     */
289	    public static Integer nationalNumberLength(String countryCode) {
290	        return countryCode == null ? null : COUNTRY_CODE_NATIONAL_LENGTHS.get(countryCode);
291	    }
292	
293	    /**
294	     * Fixed city-to-region table: the canonical region each known city belongs to
295	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
296	     * absent from this table has no known region.
297	     */
298	    private static final Map<String, String> CITY_REGIONS = Map.of(
299	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
300	
301	    /**
302	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
303	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
304	     * region string, or {@code null} when the city has no known region. This is the single
305	     * definition of the city-to-region mapping, shared by every rule that derives a region
306	     * from an owner's city.
307	     *
308	     * @param city the city to resolve
309	     * @return the canonical region, or {@code null} when the city has no known region
310	     */
311	    public static String regionForCity(String city) {
312	        return CITY_REGIONS.get(city);
313	    }
314	
315	    /**
316	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
317	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
318	     * A region absent from this table has no fixed range.
319	     */
320	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
321	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
322	
323	    /**
324	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
325	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
326	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
327	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
328	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
329	     *
330	     * @param region the region to resolve, or {@code null}
331	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
332	     */
333	    public static int[] postcodeRangeForRegion(String region) {
334	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
335	    }
336	
337	    /**
338	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
339	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
340	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
341	     * value, or falls in no known range. This is the single definition of the postcode-to-region
342	     * mapping, shared by every rule that derives a region from a postcode.
343	     *
344	     * @param postcode the postcode to resolve
345	     * @return the canonical region, or {@code null} when the postcode maps to no known region
346	     */
347	    public static String regionForPostcode(String postcode) {
348	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
349	            return null;
350	        }
351	        int value = Integer.parseInt(postcode);
352	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
353	            int[] range = entry.getValue();
354	            if (value >= range[0] && value <= range[1]) {
355	                return entry.getKey();
356	            }
357	        }
358	        return null;
359	    }
360	
361	    /**
362	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
363	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
364	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
365	     * range does derivation fall back to the fixed city-to-region table (see
366	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
367	     * resolves to a known region. This is the single definition of an owner's region, shared by
368	     * every rule that derives a region from an owner.
369	     *
370	     * @return the owner's canonical region, or {@code null} when it has no known region
371	     */
372	    @Transient
373	    public String getRegion() {
374	        String region = regionForPostcode(this.postcode);
375	        return region != null ? region : regionForCity(this.city);
376	    }
377	
378	    /**
379	     * Returns this owner's numeric membership level. The level starts at {@code 1}, gains {@code 1}
380	     * when an email is present, and gains {@code 1} when the owner has no namesakes (namesakeCount
381	     * is 0). These pre-tenure factors cap the level at {@code 3}. Level {@code 4} is reserved for
382	     * tenure and is granted only when the owner's tenure exceeds 365 days; because a newly created
383	     * owner has zero tenure, a new owner never exceeds level {@code 3}. The overall level is capped
384	     * at {@code 4}.
385	     *
386	     * @return the owner's membership level
387	     */
388	    @Transient
389	    public Integer getMembershipLevel() {
390	        int level = 1;
391	        boolean hasEmail = this.email != null && !this.email.isBlank();
392	        if (hasEmail) {
393	            level++;
394	        }
395	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
396	        if (noNamesakes) {
397	            level++;
398	        }
399	        level = Math.min(level, 3);
400	        if (this.registrationDate != null
401	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
402	            level++;
403	        }
404	        return Math.min(level, 4);
405	    }
406	
407	    /**
408	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
409	     * the last two digits of the registrationDate year, e.g. {@code 'NSW-A1B2C3D4-M26'}. Returns
410	     * {@code null} when the owner has no customer code or registration date.
411	     *
412	     * @return the owner's membership number, or {@code null} when it cannot be derived
413	     */
414	    @Transient
415	    public String getMembershipNumber() {
416	        if (this.customerCode == null || this.registrationDate == null) {
417	            return null;
418	        }
419	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
420	    }
421	
422	    /**
423	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
424	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
425	     *
426	     * @return the owner's check digit, or {@code null} when it has no customer code
427	     */
428	    @Transient
429	    public Integer getCheckDigit() {
430	        if (this.customerCode == null) {
431	            return null;
432	        }
433	        String code = this.customerCode;
434	        int sum = 0;
435	        boolean dbl = true;
436	        for (int i = code.length() - 1; i >= 0; i--) {
437	            char c = code.charAt(i);
438	            if (c < '0' || c > '9') {
439	                continue;
440	            }
441	            int d = c - '0';
442	            if (dbl) {
443	                d *= 2;
444	                if (d > 9) {
445	                    d -= 9;
446	                }
447	            }
448	            sum += d;
449	            dbl = !dbl;
450	        }
451	        return (10 - (sum % 10)) % 10;
452	    }
453	
454	    /**
455	     * Returns this owner's age band, derived from {@code birthDate} computed against
456	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
457	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
458	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
459	     * band cannot be derived. This is the single definition of an owner's age band.
460	     *
461	     * @return the owner's age band, or {@code null} when it cannot be derived
462	     */
463	    @Transient
464	    public String getAgeBand() {
465	        if (this.birthDate == null || this.registrationDate == null) {
466	            return null;
467	        }
468	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
469	        if (age < 18) {
470	            return "MINOR";
471	        }
472	        if (age < 65) {
473	            return "ADULT";
474	        }
475	        return "SENIOR";
476	    }
477	
478	    protected Set<Pet> getPetsInternal() {
479	        if (this.pets == null) {
480	            this.pets = new HashSet<>();
481	        }
482	        return this.pets;
483	    }
484	
485	    protected void setPetsInternal(Set<Pet> pets) {
486	        this.pets = pets;
487	    }
488	
489	    public List<Pet> getPets() {
490	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
491	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
492	        return Collections.unmodifiableList(sortedPets);
493	    }
494	
495	    public void setPets(List<Pet> pets) {
496	        this.pets = new HashSet<>(pets);
497	    }
498	
499	    public void addPet(Pet pet) {
500	        getPetsInternal().add(pet);
501	        pet.setOwner(this);
502	    }
503	
504	    /**
505	     * Return the Pet with the given name, or null if none found for this Owner.
506	     *
507	     * @param name to test
508	     * @return true if pet name is already in use
509	     */
510	    public Pet getPet(String name) {
511	        return getPet(name, false);
512	    }
513	
514	    /**
515	     * Return the Pet with the given name, or null if none found for this Owner.
516	     *
517	     * @param name to test
518	     * @return true if pet name is already in use
519	     */
520	    public Pet getPet(String name, boolean ignoreNew) {
521	        name = name.toLowerCase();
522	        for (Pet pet : getPetsInternal()) {
523	            if (!ignoreNew || !pet.isNew()) {
524	                String compName = pet.getName();
525	                compName = compName.toLowerCase();
526	                if (compName.equals(name)) {
527	                    return pet;
528	                }
529	            }
530	        }
531	        return null;
532	    }
533	
534	    public Pet getPet(Integer petId) {
535	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
536	    }
537	
538	    @Override
539	    public String toString() {
540	        return new ToStringCreator(this)
541	
542	            .append("id", this.getId())
543	            .append("new", this.isNew())
544	            .append("lastName", this.getLastName())
545	            .append("firstName", this.getFirstName())
546	            .append("address", this.address)
547	            .append("city", this.city)
548	            .append("telephone", this.telephone)
549	            .append("email", this.email)
550	            .toString();
551	    }
552	}
